insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('20b9e5ba-6651-50b2-9cbc-292a3a5f9a05', 'rg3-word-parts-p02', (select id from public.skills where slug = 'read-g3-word-parts'), null,
        '3-5', $q$The Lamplighters$q$, $q$Long ago, before cities had electric lights, streets were dark at night. Many towns hired workers called lamplighters. Each evening, a lamplighter walked from post to post with a long pole.

At the top of each post was a glass lamp that burned gas or oil. The lamplighter used the pole to open the lamp and light the flame. This was a nightly job. Lamplighters worked every single evening, even in rain and snow.

The work had to be done with care. A flame that was unsafe could start a fire. Lamplighters checked each lamp and cleaned the smoky glass so the light could shine through.

In the morning, the lamplighters came back. They put out each flame so no fuel was wasted. If a lamp had blown out in the wind, they would relight it the next evening.

Today, most streetlights turn on by themselves. Still, some towns keep a few old gas lamps. People enjoy them because they are a reminder of the past. The soft glow brings a feeling of calmness to the street.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
