-- Passage rg4-character-setting-plot-p03
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('ee214064-ad1b-53eb-9f73-5d759cfbcfab', 'rg4-character-setting-plot-p03', (select id from public.skills where slug = 'read-g4-character-setting-plot'), null,
        '3-5', $q$The Otter and the Turtle$q$, $q$One spring morning, Mother Duck rushed across the pond in a panic. "My smallest duckling is missing!" she cried.

Quick Otter leaped into the water at once. "I will find him!" he shouted. He zoomed to the north shore and back. He dashed under the bridge and out again. He splashed so hard that the water turned brown with mud. He never stopped to look closely at anything.

Old Turtle climbed slowly onto a flat rock. She did not swim at all. Instead, she closed her eyes and listened. The frogs were croaking. The wind was rustling the cattails. Then, under all the other sounds, she heard a tiny peep.

"The peep is coming from the tall reeds by the willow tree," Turtle said. "Ducklings hide in reeds when they are frightened."

Mother Duck paddled to the willow tree. There, tucked between the reeds, was her smallest duckling. He had been too scared of Otter's splashing to come out.

Otter climbed onto the bank, dripping and out of breath. "How did you find him without even moving?" he asked.

Turtle smiled. "You were busy searching," she said. "I was busy noticing."$q$, 'draft')
