insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('471a7fff-920b-5db7-a545-36572ab784df', 'rg4-figurative-language-p01', (select id from public.skills where slug = 'read-g4-figurative-language'), null,
        '3-5', $q$Lena's First Glide$q$, $q$Lena Kowalczyk stood at the edge of the ice rink. Her legs felt as wobbly as cooked noodles. The other skaters zipped past her like swallows over a pond.

Her coach, Mr. Adebayo, skated over with a smile. "Everyone starts somewhere," he said. "Rome wasn't built in a day." He showed her how to bend her knees and push with one foot at a time.

Lena tried. She slipped and landed on the cold ice. Her cheeks turned red. She wanted to throw in the towel and go home. But her best friend Rosa waved from the bleachers and cheered her on.

Lena got back up. Push, glide. Push, glide. Slowly, her stiff legs grew loose. The ice was no longer her enemy. It was a smooth, shiny road that carried her forward.

By the end of the hour, Lena could skate all the way around the rink without falling. She was not fast, but she was steady. Mr. Adebayo clapped his gloved hands. "You were a turtle at first," he said, "but now you are a swan."

Lena laughed. Her legs were tired, but her heart felt as light as a feather.$q$, 'draft')
