-- Passage rg4-figurative-language-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('b8088318-cdfd-53d8-a11f-968358a5c2b2', 'rg4-figurative-language-p05', (select id from public.skills where slug = 'read-g4-figurative-language'), null,
        '3-5', $q$A Friend on the First Day$q$, $q$Omar Haddad's family moved to a new city in the middle of the school year. On his first morning, the school hallway felt like a maze. Every door looked the same, and every face belonged to a stranger.

At lunch, Omar sat alone. He felt like a fish out of water. Then a girl with curly hair sat down across from him. "I'm Priya," she said. "You're the new kid on the block, right?"

Omar nodded. He did not know what to say.

Priya did not seem to mind. She talked about the art club, the class pet turtle, and the best swing on the playground. Her words came out as fast as a waterfall. Soon Omar was laughing.

"Do you like to draw?" Priya asked.

Omar's face lit up. Drawing was his favorite thing in the world. He pulled a sketchbook from his backpack and showed her his pictures of birds and buildings.

"These are amazing," Priya said. "You should join art club. We meet on Thursdays."

That afternoon, Omar walked home slowly. The city still felt big, but it felt a little less lonely. He had made one friend. He remembered what his grandmother liked to say: "Little by little, a little becomes a lot."$q$, 'draft')
