-- Passage rg4-literary-structure-pov-p01
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('7f7a04de-cb81-52d3-96ed-248795fbabfc', 'rg4-literary-structure-pov-p01', (select id from public.skills where slug = 'read-g4-literary-structure-pov'), null,
        '3-5', $q$The Paper Dragon$q$, $q$Every spring, our town holds a kite festival at Miller Field. This year I decided to build my own kite instead of buying one.

I chose a dragon shape with a long tail made from strips of old newspaper. My little brother Tomas helped me paint green scales on the wings. It took us four afternoons, and our kitchen table was covered in glue.

On the morning of the festival, the wind was strong. My hands shook as I let out the string. For a moment, the dragon dipped toward the grass, and my stomach dipped with it. Then a gust caught the wings, and the kite climbed higher than the trees.

Tomas jumped up and down. "Go, Lina! Fly it higher, sister!" he shouted. A woman next to us asked where we had bought such a fine kite. I felt my face get warm.

"We made it," I said. Then I handed Tomas the string so he could feel the dragon pull.$q$, 'draft')
