  ('77d450d4-6ed6-57c2-a80e-4a0f2e413a3f', null, (select id from public.skills where slug = 'read-g4-literary-structure-pov'), null, 'hard',
   $q$If this story were retold by a third person narrator, how would the sentence "My hands shook as I let out the string" most likely change?$q$, $q$[{"text":"\"Your hands shook as you let out the string.\"","is_correct":false,"misconception_token":"confuses-second-person"},{"text":"\"Tomas's hands shook as he let out the string.\"","is_correct":false,"misconception_token":"changes-character"},{"text":"\"My hands shook as Lina let out the string.\"","is_correct":false,"misconception_token":"mixes-points-of-view"},{"text":"\"Lina's hands shook as she let out the string.\"","is_correct":true}]$q$::jsonb, $q$"Lina's hands shook as she let out the string."$q$, $q$A third person narrator calls the character by name and uses "she" instead of "I," so the sentence becomes "Lina's hands shook as she let out the string." Mixing "My" with "Lina" blends two points of view, and the Tomas choice changes who is doing the action.$q$, 'draft', '7f7a04de-cb81-52d3-96ed-248795fbabfc')
